<script lang="ts">
	import { BarChart, AreaChart, PieChart } from 'layerchart';
	import { stateQuery } from 'dexie-svelte-query';
	import { onMount } from 'svelte';
	import { db, GLOBAL_FOLDER_ID } from '$lib/db/database';
	import { getMonday, getWeekDates, toDateKey } from '$lib/utils/weeks';
	import {
		formatShortNumber,
		buildCountsIndex,
		computeDailyData,
		computeSixWeekAverages,
		computeWeeklyFolderStats,
		computeLastThreeMonths
	} from '$lib/utils/stats';

	type Folder = {
		id: number;
		name: string;
		icon: string | null;
		weeklyWordGoal: number | null;
		deletedAt: string | null;
	};
	type WeeklyFolderStats = {
		folder: Folder;
		words: number;
		goal: number;
		percentage: number;
		dailyData: { day: string; words: number }[];
	};
	type DailyAverageData = { week: string; dailyAverage: number };

	let dailyAverageData = $state<DailyAverageData[]>([]);
	let currentWeekDailyAverage = $state(0);
	let totalWords = $state(0);
	let folders = $state<Folder[]>([]);
	let weeklyFolderStats = $state<WeeklyFolderStats[]>([]);
	let globalWeeklyWords = $state(0);
	let globalDailyData = $state<{ day: string; words: number }[]>([]);
	let lastThreeMonthsData = $state<Record<string, string | number>[]>([]);
	let lastThreeMonthsSeries = $state<{ key: string; label: string }[]>([]);
	let isLoading = $state(true);
	let loadError = $state<string | null>(null);
	const dayLabels = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

	const foldersQuery = stateQuery(() =>
		db.folders
			.filter(
				(folder) => folder.deletedAt === null && (folder.hasWeeklyWordGoal || folder.hasWordGoal)
			)
			.toArray()
	);

	let allowedFolders = $derived(foldersQuery.current);
	let showStats = $derived(!!allowedFolders?.length);

	async function loadStats() {
		isLoading = true;
		loadError = null;
		try {
			const [allFolders, allCountRows, posts] = await Promise.all([
				db.folders.filter((f) => f.hasWeeklyWordGoal).toArray(),
				db.dailyWordCounts.toArray(),
				db.posts.filter((p) => !p.deletedAt).toArray()
			]);

			folders = allFolders;
			const countsByKey = buildCountsIndex(allCountRows);
			const weekDates = getWeekDates();

			globalDailyData = computeDailyData(weekDates, dayLabels, GLOBAL_FOLDER_ID, countsByKey);
			globalWeeklyWords = globalDailyData.reduce((total, item) => total + item.words, 0);
			currentWeekDailyAverage = Math.round(globalWeeklyWords / weekDates.length);

			dailyAverageData = computeSixWeekAverages(getMonday(new Date()), countsByKey);

			totalWords = posts.reduce((total, post) => total + (post.wordCount ?? 0), 0);

			weeklyFolderStats = computeWeeklyFolderStats(folders, weekDates, dayLabels, countsByKey);

			const { series, data } = computeLastThreeMonths(folders, countsByKey);
			lastThreeMonthsSeries = series;
			lastThreeMonthsData = data;
		} catch (error) {
			console.error(error);
			loadError = 'Failed to load writing statistics';
		} finally {
			isLoading = false;
		}
	}

	onMount(() => {
		void loadStats();
	});
</script>

