								<i class="hgi hgi-stroke hgi-rounded hgi-folder-01 initial"></i>
								<span>{folderStat.folder.name}</span>
							</div>
						</div>
						<div class="stats-item-content">
							<div class="stat">
								<span class="stat-number">
									{Math.round(folderStat.percentage)}%
								</span>
								<span class="stat-byline number">
									{formatShortNumber(folderStat.words)}/{formatShortNumber(folderStat.goal)}
								</span>
							</div>

							<div class="stat-chart">
								<PieChart
									data={[
										{
											key: 'written',
											label: 'Written',
											value: Math.min(folderStat.words, folderStat.goal),
											color: 'var(--color-text)'
										},
										{
											key: 'remaining',
											label: 'Remaining',
											value: Math.max(folderStat.goal - folderStat.words, 0),
											color: 'var(--color-border-mid)'
										}
									]}
									key="key"
									label="label"
									value="value"
									c="color"
									innerRadius={14}
									legend={false}
									props={{ pie: { sort: null } }}
									tooltip={false}
								/>
							</div>
						</div>
					</div>
				{/each}
			</div>
