			display: flex;
			flex-direction: column;
			border-bottom: 1px solid var(--color-border);
			.big-number {
				font-size: var(--step-5);
				color: var(--color-text-standout);
				font-weight: 666;
			}
		}
		h2,
		h1 {
			width: clamp(320px, 90vw, 1120px);
			margin: auto;
			padding-left: var(--space-s);
			margin-top: var(--space-l);
			margin-bottom: Var(--space-s);
		}
		.stats-row {
			display: flex;
			gap: var(--space-l);
			width: clamp(320px, 90vw, 1120px);
			margin: auto;
			&:not(.full) {
				display: grid;
				grid-template-columns: 1fr 1fr 1fr;
			}
		}
		.stats-item {
			display: flex;
			flex-grow: 1;
			flex-direction: column;
			border: 1px solid var(--color-border);
			box-shadow: var(--shadow-elevation-low);
			border-radius: var(--radius-m);
			padding: var(--space-s);
		}
		.stats-item-header {
			color: var(--color-text-muted);
			font-weight: 444;
			.folder-progress {
				padding-left: 0;
				&:hover {
					background: transparent;
				}
			}
		}
		.stats-item-content {
			display: flex;
			justify-content: space-between;
			align-items: end;
			margin-top: var(--space-m);
			.stat-number {
				font-size: var(--step-4);
				font-weight: 666;
			}
			.stat-byline {
				color: var(--color-text-muted);
				font-weight: 444;
				&.number {
					font-family: var(--font-family-mono);
					font-weight: 200;
				}
			}
		}
		.stat-number {
			display: flex;
			flex-direction: column;
		}
		.stat-chart {
			width: 90px;
			height: 40px;
		}

		.stats-top {
			width: clamp(440px, 66vw, 900px);
			margin: auto;
			display: flex;
			gap: var(--space-l);
		}
		.stats-item {
			border-radius: var(--radius-m);
		}
		.stats-hero {
			display: flex;
			flex-direction: column;
			border: 1px solid var(--color-border);
			box-shadow: var(--shadow-elevation-low);
			border-radius: var(--radius-m);
			flex-grow: 1;
			overflow: hidden;
			.stats-hero-content {
				padding: var(--space-s);
			}
			.big-number {
				font-size: calc(var(--step-5) * 1.333 * 1.333 * 1.333);
				font-weight: 666;
				text-align: center;
				margin: 0;
				line-height: 1;
			}
			.stat-byline {
				font-size: var(--step-1);
				text-align: center;
				color: var(--color-text-muted);
				margin: 0;
